import { Column, Text } from '@umami/react-zen';
import { memo } from 'react';
import type { BoardComponentConfig } from '@/lib/types';
import { getComponentDefinition } from '../boardComponentRegistry';

function BoardComponentRendererComponent({
  config,
  websiteId,
  entityType,
  isPreview,
}: {
  config: BoardComponentConfig;
  websiteId?: string;
  entityType?: string;
  isPreview?: boolean;
}) {
  const definition = getComponentDefinition(config.type);

  if (!definition) {
    return (
      <Column alignItems="center" justifyContent="center" width="100%" height="100%">
        <Text color="muted">Unknown component: {config.type}</Text>
      </Column>
    );
  }

  const Component =
    (entityType && definition.componentByEntityType?.[entityType]) || definition.component;

  if (!websiteId && definition.requiresWebsite !== false) {
    return (
      <Column alignItems="center" justifyContent="center" width="100%" height="100%">
        <Text color="muted">Select a website</Text>
      </Column>
    );
  }

  return (
    <Component
      {...(websiteId ? { websiteId } : {})}
      {...(isPreview ? { isPreview } : {})}
      {...config.props}
    />
  );
}

export const BoardComponentRenderer = memo(
  BoardComponentRendererComponent,
  (prevProps, nextProps) =>
    prevProps.websiteId === nextProps.websiteId &&
    prevProps.entityType === nextProps.entityType &&
    prevProps.isPreview === nextProps.isPreview &&
    prevProps.config === nextProps.config,
);

BoardComponentRenderer.displayName = 'BoardComponentRenderer';

import { Button, Column, ListItem, Row, Select, Text, TextField } from '@umami/react-zen';
import { useEffect, useMemo, useState } from 'react';
import { useApi, useMessages } from '@/components/hooks';
import { useModified } from '@/components/hooks/useModified';
import { LinkSelect } from '@/components/input/LinkSelect';
import { PixelSelect } from '@/components/input/PixelSelect';
import { WebsiteSelect } from '@/components/input/WebsiteSelect';
import {
  BOARD_ENTITY_TYPES,
  type BoardEntityType,
  type BoardType,
  getComponentEntity,
  isBoardComponentSupported,
  isOpenBoardType,
} from '@/lib/boards';
import type { BoardComponentConfig } from '@/lib/types';
import {
  type ComponentDefinition,
  type ConfigField,
  getComponentDefinitions,
} from '../boardComponentRegistry';
import { BoardComponentRenderer } from './BoardComponentRenderer';

const COMPONENT_GROUP_ORDER: string[] = [
  'Traffic',
  'Events',
  'Behavior',
  'Realtime',
  'Growth',
  'Revenue',
  'Content',
];

export function BoardComponentSelect({
  teamId,
  boardType,
  boardEntityType,
  boardEntityId,
  initialConfig,
  onSelect,
  onClose,
}: {
  teamId?: string;
  boardType: BoardType;
  boardEntityType?: BoardEntityType;
  boardEntityId?: string;
  initialConfig?: BoardComponentConfig;
  onSelect: (config: BoardComponentConfig) => void;
  onClose: () => void;
}) {
  const { t, labels, messages } = useMessages();
  const { get, useQuery } = useApi();
  const initialEntity = getComponentEntity(initialConfig);
  const [selectedDef, setSelectedDef] = useState<ComponentDefinition | null>(null);
  const [configValues, setConfigValues] = useState<Record<string, any>>({});
  const [selectedEntityType, setSelectedEntityType] = useState<BoardEntityType>(
    initialEntity.entityType || boardEntityType || BOARD_ENTITY_TYPES.website,
  );
  const [selectedEntityId, setSelectedEntityId] = useState(initialEntity.entityId || boardEntityId);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');

  const allDefinitions = useMemo(() => getComponentDefinitions(), []);
  const activeEntityType = isOpenBoardType(boardType) ? selectedEntityType : boardEntityType;
  const isSelectedDefSupported = selectedDef
    ? isBoardComponentSupported(selectedDef.type, activeEntityType)
    : false;

  const getDefaultConfigValues = (
    def: ComponentDefinition,
    config?: BoardComponentConfig,
    entityType?: BoardEntityType,
  ) => {
    const defaults: Record<string, any> = {};

    for (const field of def.configFields ?? []) {
      defaults[field.name] = field.defaultValue;
    }

    if (def.defaultProps) {
      Object.assign(defaults, def.defaultProps);
    }

    for (const field of def.configFields ?? []) {
      if (field.type !== 'select') {
        continue;
      }

      const options = (entityType && field.optionsByEntityType?.[entityType]) ?? field.options;
      const currentValue = defaults[field.name];

      if (
        options?.length &&
        !options.some(option => String(option.value) === String(currentValue))
      ) {
        defaults[field.name] = options[0].value;
      }
    }

    if (config?.props) {
      Object.assign(defaults, config.props);
    }

    return defaults;
  };

  useEffect(() => {
    if (!initialConfig) {
      return;
    }

    const definition = allDefinitions.find(def => def.type === initialConfig.type);

    if (!definition) {
      return;
    }

    setSelectedDef(definition);
    const entityType = initialEntity.entityType || boardEntityType || BOARD_ENTITY_TYPES.website;
    setConfigValues(getDefaultConfigValues(definition, initialConfig, entityType));
    setSelectedEntityType(entityType);
    setSelectedEntityId(initialEntity.entityId || boardEntityId);
    setTitle(initialConfig.title ?? definition.name);
    setDescription(initialConfig.description || '');
  }, [
    initialConfig,
    allDefinitions,
    boardEntityId,
    boardEntityType,
    initialEntity.entityId,
    initialEntity.entityType,
  ]);

  const handleSelectComponent = (def: ComponentDefinition) => {
    setSelectedDef(def);
    setConfigValues(getDefaultConfigValues(def, undefined, activeEntityType));
    setTitle(def.name);
    setDescription('');
  };

  const handleConfigChange = (name: string, value: any) => {
    setConfigValues(prev => ({ ...prev, [name]: value }));
  };

  const needsWebsite = selectedDef?.requiresWebsite !== false;
  const isOpenType = isOpenBoardType(boardType);
  const hasSelectedEntity = isOpenType ? !!selectedEntityId : !!boardEntityId;
  const resolvedEntityType = needsWebsite
    ? isOpenType
      ? selectedEntityType
      : boardEntityType
    : undefined;
  const resolvedEntityId = needsWebsite
    ? isOpenType
      ? selectedEntityId
      : boardEntityId
    : undefined;
  const reportFields = selectedDef?.configFields?.filter(
    field => field.type === 'report' && field.reportType,
  );
  const { modified: funnelsModified } = useModified('websites:funnels');
  const { modified: goalsModified } = useModified('websites:goals');
  const { data: reportOptionsData, isLoading: isLoadingReportOptions } = useQuery({
    queryKey: [
      'board-component-report-options',
      funnelsModified,
      goalsModified,
      {
        websiteId: resolvedEntityId,
        reportTypes: reportFields?.map(field => field.reportType).join(','),
      },
    ],
    queryFn: async () => {
      const types = [...new Set(reportFields?.map(field => field.reportType).filter(Boolean))];

      const entries = await Promise.all(
        types.map(async type => {
          const response = await get(`/websites/${resolvedEntityId}/${type}s`, {
            pageSize: 1000,
          });

          return [type, response.data] as const;
        }),
      );

      return Object.fromEntries(entries);
    },
    enabled: !!resolvedEntityId && !!reportFields?.length,
  });
  const reportOptionsByType = reportOptionsData ?? {};
  const hasRequiredConfig = selectedDef
    ? (selectedDef.configFields ?? []).every(field => {
        if (!field.required) {
          return true;
        }

        const value = configValues[field.name];
        return value !== undefined && value !== null && value !== '';
      })
    : false;

  const handleEntityTypeChange = (value: string) => {
    setSelectedEntityType(value as BoardEntityType);
    setSelectedEntityId(undefined);
    setSelectedDef(null);
    setConfigValues({});
    setTitle('');
    setDescription('');
  };

  const handleAdd = () => {
    if (!selectedDef || !isSelectedDefSupported || (needsWebsite && !resolvedEntityId)) return;

    const props: Record<string, any> = {};

    if (selectedDef.defaultProps) {
      Object.assign(props, selectedDef.defaultProps);
    }

    Object.assign(props, configValues);

    for (const field of selectedDef.configFields ?? []) {
      if (field.type === 'number' && props[field.name] != null && props[field.name] !== '') {
        props[field.name] = Number(props[field.name]);
      }
    }

    const config: BoardComponentConfig = {
      type: selectedDef.type,
      ...(needsWebsite && isOpenType && resolvedEntityId
        ? { entityType: resolvedEntityType, entityId: resolvedEntityId }
        : {}),
      title,
      description,
    };

    if (Object.keys(props).length > 0) {
      config.props = props;
    }

    onSelect(config);
  };

  const previewConfig: BoardComponentConfig | null = useMemo(
    () =>
      selectedDef
        ? {
            type: selectedDef.type,
            props: { ...selectedDef.defaultProps, ...configValues },
          }
        : null,
    [selectedDef, configValues],
  );

  const canSave =
    !!selectedDef &&
    isSelectedDefSupported &&
    hasRequiredConfig &&
    (!needsWebsite || !!resolvedEntityId);
  const availableDefinitions = useMemo(
    () =>
      allDefinitions.filter(
        def =>
          isBoardComponentSupported(def.type, activeEntityType) || def.type === selectedDef?.type,
      ),
    [activeEntityType, allDefinitions, selectedDef?.type],
  );
  const groupedDefinitions = useMemo(() => {
    const order = new Map(COMPONENT_GROUP_ORDER.map((group, index) => [group, index]));
    const groups = new Map<string, ComponentDefinition[]>();

    for (const def of availableDefinitions) {
      const group = def.group ?? 'Other';
      const items = groups.get(group) ?? [];
      items.push(def);
      groups.set(group, items);
    }

    return Array.from(groups.entries())
      .sort(([a], [b]) => {
        const left = order.get(a) ?? Number.MAX_SAFE_INTEGER;
        const right = order.get(b) ?? Number.MAX_SAFE_INTEGER;

        if (left !== right) {
          return left - right;
        }

        return a.localeCompare(b);
      })
      .map(([group, definitions]) => ({
        group,
        definitions,
      }));
  }, [availableDefinitions]);

  return (
    <Column gap="4">
      <Row gap="6" style={{ height: 600 }}>
        <Column gap="3" style={{ width: 280, flexShrink: 0, overflowY: 'auto' }}>
          <Text weight="bold">{t(labels.properties)}</Text>

          {needsWebsite && isOpenType && (
            <>
              <Column gap="2">
                <Text size="sm" color="muted">
                  {t(labels.type)}
                </Text>
                <Select
                  value={selectedEntityType}
                  onChange={value => handleEntityTypeChange(value as string)}
                >
                  <ListItem id={BOARD_ENTITY_TYPES.website}>{t(labels.website)}</ListItem>
                  <ListItem id={BOARD_ENTITY_TYPES.pixel}>{t(labels.pixel)}</ListItem>
                  <ListItem id={BOARD_ENTITY_TYPES.link}>{t(labels.link)}</ListItem>
                </Select>
              </Column>
              <Column gap="2">
                <Text size="sm" color="muted">
                  {selectedEntityType === BOARD_ENTITY_TYPES.pixel
                    ? t(labels.pixel)
                    : selectedEntityType === BOARD_ENTITY_TYPES.link
                      ? t(labels.link)
                      : t(labels.website)}
                </Text>
                {selectedEntityType === BOARD_ENTITY_TYPES.pixel ? (
                  <PixelSelect
                    pixelId={selectedEntityId}
                    teamId={teamId}
                    placeholder={t(labels.selectPixel)}
                    onChange={value => setSelectedEntityId(value as string)}
                  />
                ) : selectedEntityType === BOARD_ENTITY_TYPES.link ? (
                  <LinkSelect
                    linkId={selectedEntityId}
                    teamId={teamId}
                    placeholder={t(labels.selectLink)}
                    onChange={value => setSelectedEntityId(value as string)}
                  />
                ) : (
                  <WebsiteSelect
                    websiteId={selectedEntityId}
                    teamId={teamId}
                    placeholder={t(labels.selectWebsite)}
                    onChange={value => setSelectedEntityId(value as string)}
                  />
                )}
              </Column>
            </>
          )}

          <Column gap="2">
            <Text size="sm" color="muted">
              {t(labels.title)}
            </Text>
            <TextField value={title} onChange={setTitle} autoComplete="off" />
          </Column>

          <Column gap="2">
            <Text size="sm" color="muted">
              {t(labels.description)}
            </Text>
            <TextField value={description} onChange={setDescription} autoComplete="off" />
          </Column>

          {selectedDef?.configFields && selectedDef.configFields.length > 0 && (
            <Column gap="3">
              {selectedDef.configFields.map((field: ConfigField) => (
                <Column key={field.name} gap="2">
                  <Text size="sm" color="muted">
                    {field.label}
                  </Text>

                  {field.type === 'select' && (
                    <Select
                      value={String(configValues[field.name] ?? field.defaultValue ?? '')}
                      onChange={value => handleConfigChange(field.name, value as string)}
                      maxHeight={300}
                      popoverProps={{ style: { width: 220 } }}
                    >
                      {(field.optionsByEntityType?.[activeEntityType] ?? field.options)?.map(
                        option => (
                          <ListItem key={option.value} id={option.value}>
                            {option.label}
                          </ListItem>
                        ),
                      )}
                    </Select>
                  )}

                  {field.type === 'text' && (
                    <TextField
                      value={String(configValues[field.name] ?? field.defaultValue ?? '')}
                      onChange={(value: string) => handleConfigChange(field.name, value)}
                    />
                  )}

                  {field.type === 'number' && (
                    <TextField
                      type="number"
                      value={String(configValues[field.name] ?? field.defaultValue ?? '')}
                      onChange={(value: string) => handleConfigChange(field.name, value)}
                    />
                  )}

                  {field.type === 'textarea' && (
                    <TextField
                      asTextArea
                      value={String(configValues[field.name] ?? field.defaultValue ?? '')}
                      onChange={(value: string) => handleConfigChange(field.name, value)}
                      style={{ minHeight: 200 }}
                    />
                  )}

                  {field.type === 'report' && (
                    <>
                      <Select
                        value={String(configValues[field.name] ?? field.defaultValue ?? '')}
                        onChange={value => handleConfigChange(field.name, value as string)}
                        maxHeight={300}
                        popoverProps={{ style: { width: 220 } }}
                      >
                        {(reportOptionsByType[field.reportType ?? ''] ?? []).map(option => (
                          <ListItem key={option.id} id={option.id}>
                            {option.name}
                          </ListItem>
                        ))}
                      </Select>
                      {isLoadingReportOptions && (
                        <Text size="xs" color="muted">
                          Loading options...
                        </Text>
                      )}
                      {!isLoadingReportOptions &&
                        resolvedEntityId &&
                        (reportOptionsByType[field.reportType ?? '']?.length ?? 0) === 0 && (
                          <Text size="xs" color="muted">
                            No saved items found.
                          </Text>
                        )}
                    </>
                  )}
                </Column>
              ))}
            </Column>
          )}
        </Column>

        <Column gap="3" height="100%" style={{ width: 280, flexShrink: 0, minWidth: 0 }}>
          <Text weight="bold">Components</Text>
          <Column border="left" paddingLeft="4" height="100%" style={{ minHeight: 0 }}>
            {hasSelectedEntity ? (
              <Column gap="1" height="100%" style={{ overflowY: 'auto', minHeight: 0 }}>
                {groupedDefinitions.map(({ group, definitions }) => (
                  <Column key={group} gap="1" paddingBottom="2">
                    <Text size="sm" color="muted" weight="bold">
                      {group}
                    </Text>
                    {definitions.map(def => {
                      const Icon = def.icon;

                      return (
                        <Row
                          key={def.type}
                          tabIndex={0}
                          gap="3"
                          alignItems="flex-start"
                          paddingX="3"
                          paddingY="2"
                          borderRadius
                          backgroundColor={
                            selectedDef?.type === def.type ? 'surface-sunken' : undefined
                          }
                          hover={{ backgroundColor: 'surface-sunken' }}
                          style={{ cursor: 'pointer' }}
                          onClick={() => handleSelectComponent(def)}
                        >
                          <Icon size={16} />
                          <Column gap="1">
                            <Text
                              size="sm"
                              weight={selectedDef?.type === def.type ? 'bold' : undefined}
                            >
                              {def.name}
                            </Text>
                            <Text size="xs" color="muted">
                              {def.description}
                            </Text>
                          </Column>
                        </Row>
                      );
                    })}
                  </Column>
                ))}
              </Column>
            ) : (
              <Column alignItems="center" justifyContent="center" height="100%">
                <Text color="muted">{t(messages.selectBoardEntityFirst)}</Text>
              </Column>
            )}
          </Column>
        </Column>

        <Column gap="3" flexGrow={1} height="100%" style={{ minWidth: 0 }}>
          <Text weight="bold">Preview</Text>
          <Column border="left" paddingLeft="4" height="100%" style={{ minWidth: 0 }}>
            {hasSelectedEntity && previewConfig && (!needsWebsite || resolvedEntityId) ? (
              <BoardComponentRenderer
                config={previewConfig}
                websiteId={resolvedEntityId}
                entityType={resolvedEntityType}
                isPreview
              />
            ) : (
              <Column alignItems="center" justifyContent="center" height="100%">
                <Text color="muted">
                  {!hasSelectedEntity
                    ? t(messages.selectBoardEntityFirst)
                    : resolvedEntityId
                      ? t(messages.selectComponentPreview)
                      : t(messages.selectBoardEntityFirst)}
                </Text>
              </Column>
            )}
          </Column>
        </Column>
      </Row>

      <Row justifyContent="flex-end" gap="2" paddingTop="4">
        <Button variant="quiet" onPress={onClose}>
          {t(labels.cancel)}
        </Button>
        <Button variant="primary" onPress={handleAdd} isDisabled={!canSave}>
          {t(labels.save)}
        </Button>
      </Row>
    </Column>
  );
}

