  const { isMobile } = useMobile();
  const { data } = useGoalDefinitionQuery(websiteId, id);
  const { mutateAsync, error, isPending, touch } = useUpdateQuery(
    `/websites/${websiteId}/goals${id ? `/${id}` : ''}`,
