                </Column>
              ) : (
                <Grid columns="260px 1fr" gap>
                  <Column style={{ minWidth: 0 }}>
                    <FormField name="parameters.type" rules={{ required: t(labels.required) }}>
                      <ActionSelect />
                    </FormField>
                  </Column>
                  <Column style={{ minWidth: 0 }}>
                    <FormField name="parameters.value" rules={{ required: t(labels.required) }}>
                      {({ field }) => {
