src/components/modals/TwoFactorSetupModa:
'use client';
import { useQueryClient } from '@tanstack/react-query';
import {
  Alert,
  AlertTitle,
  Box,
  Button,
  Code,
  Column,
  Dialog,
  Icon,
  Image,
  Modal,
  Row,
  Tag,
  TagGroup,
  Text,
} from '@umami/react-zen';
import { LucideCopy } from 'lucide-react';
import { type ReactNode, useEffect, useState } from 'react';
import { ControlledDialog } from '@/components/common/ControlledDialog';
import { OtpInput } from '@/components/common/OtpInput';
import { useMessages, useUpdateQuery } from '@/components/hooks';
import styles from './TwoFactorSetupModal.module.css';
import { TwoFactorSuccessModal } from './TwoFactorSuccessModal';

function Step({
  tag,
  title,
  details,
  children,
}: {
  tag: string;
  title: string;
  details: string;
  children: ReactNode;
}) {
  return (
    <Column gap="5">
      <Column gap="3">
        <Row gap="3" alignItems="center">
          <TagGroup>
            <Tag variant="primary">{tag}</Tag>
          </TagGroup>
          <Text weight="bold">{title}</Text>
        </Row>
        <Text>{details}</Text>
      </Column>
      {children}
    </Column>
  );
}

interface TwoFactorSetupModalProps {
  required: boolean;
  onClose?: () => void;
}

export function TwoFactorSetupModal({ required, onClose }: TwoFactorSetupModalProps) {
  const { t, labels, messages, getErrorMessage } = useMessages();
  const [qrCodeDataUrl, setQrCodeDataUrl] = useState<string | null>(null);
  const [manualKey, setManualKey] = useState<string | null>(null);
  const [otpValue, setOtpValue] = useState('');
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [backupCodes, setBackupCodes] = useState<string[] | null>(null);

  const queryClient = useQueryClient();
  const { mutate: initiate } = useUpdateQuery('/2fa/setup/initiate');
  const { mutateAsync: confirm, isPending: isConfirming } = useUpdateQuery('/2fa/setup/confirm');
  const { mutate: cancel } = useUpdateQuery('/2fa/setup/cancel');

  useEffect(() => {
    initiate(
      {},
      {
        onSuccess: (data: any) => {
          setQrCodeDataUrl(data.qrCodeDataUrl);
          setManualKey(data.manualKey);
        },
        onError: (err: any) => setError(getErrorMessage(err) || t(messages.error)),
      },
    );
  }, []);

  const handleConfirm = async (value?: string) => {
    const token = value ?? otpValue;
    if (token.length !== 6) return;
    setError(null);
    try {
      const data: any = await confirm({ token });
      setBackupCodes(data.backupCodes);
    } catch (err: any) {
      setError(getErrorMessage(err) || t(messages.error));
    }
  };

  const handleCancel = async () => {
    cancel({});
    onClose?.();
  };

  const handleCopy = () => {
    if (manualKey) {
      navigator.clipboard.writeText(manualKey);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  if (backupCodes) {
    return (
      <TwoFactorSuccessModal
        backupCodes={backupCodes}
        onClose={() => {
          queryClient.invalidateQueries({ queryKey: ['2fa-status'] });
          onClose?.();
        }}
      />
    );
  }

  const preventDismiss = required ? () => {} : undefined;

  return (
    <ControlledDialog>
      <Modal isOpen={true} onOpenChange={preventDismiss}>
        <Dialog title={t(labels.twoFactorSetupTitle)} className={styles.twoFactorSetupModal}>
          {() => (
            <Column gap="9">
              <Text>
                {required && `${t(messages.twoFactorSetupRequiredDescription)} `}
                {t(messages.twoFactorSetupDescription)}
              </Text>

              {/* Step 1 - Scan QR Code */}
              <Step
                tag={t(labels.twoFactorStep1)}
                title={t(labels.twoFactorScanQr)}
                details={t(messages.twoFactorStep1Description)}
              >
                <Box padding="2" shadow="lg" borderRadius="lg" border width="fit">
                  <Row alignItems="center" gap="2">
                    {qrCodeDataUrl && (
                      <Image
                        src={qrCodeDataUrl}
                        alt="QR code"
                        className={styles.qrCodeImage}
                        borderRadius="lg"
                      />
                    )}
                    <Column>
                      <Text weight="bold">{t(labels.twoFactorCantScan)}</Text>
                      <Column gap="2">
                        <Text size="sm">{t(labels.twoFactorManualEntry)}</Text>
                        <Code>{manualKey}</Code>
                        <div>
                          <Button variant="outline" onPress={handleCopy}>
                            <Icon size="sm">
                              <LucideCopy />
                            </Icon>
                            {copied ? t(labels.twoFactorCodeCopied) : t(labels.twoFactorCopyCode)}
                          </Button>
                        </div>
                      </Column>
                    </Column>
                  </Row>
                </Box>
              </Step>

              {/* Step 2 - Enter Verification Code */}
              <Step
                tag={t(labels.twoFactorStep2)}
                title={t(labels.twoFactorGetCode)}
                details={t(messages.twoFactorStep2Description)}
              >
                <Column gap="3.5">
                  <Text size="sm" weight="bold">
                    {t(labels.twoFactorEnterCode)}
                  </Text>
                  <OtpInput
                    value={otpValue}
                    onChange={val => {
                      setOtpValue(val);
                      if (error) setError(null);
                    }}
                    onComplete={handleConfirm}
                    disabled={isConfirming}
                  />
                </Column>
              </Step>

              {error && (
                <Alert variant="danger">
                  <AlertTitle>{error}</AlertTitle>
                </Alert>
              )}

              <Row gap="2" justifyContent="flex-end">
                {!required && (
                  <Button variant="outline" onPress={handleCancel} isDisabled={isConfirming}>
                    {t(labels.cancel)}
                  </Button>
                )}
                <Button
                  variant="primary"
                  onPress={() => handleConfirm()}
                  isDisabled={otpValue.length !== 6 || isConfirming || !!error}
                >
                  {t(labels.confirm)}
                </Button>
              </Row>
            </Column>
          )}
        </Dialog>
      </Modal>
    </ControlledDialog>
  );
}

src/components/share/SharedSharesTable.t:
import { Icon, Row, Text } from '@umami/react-zen';
import type { ReactNode } from 'react';
import { CopyButton } from '@/components/common/CopyButton';
import { useConfig, useMessages, useMobile } from '@/components/hooks';
import { ExternalLink } from '@/components/icons';

const desktopGridTemplateColumns = 'minmax(180px, 1fr) minmax(0, 2fr) auto';
const rowBorder = '1px solid var(--zen-border)';

export interface ShareRow {
  id: string;
  name: string;
  slug: string;
}

export function SharedSharesTable({
  data = [],
  renderActions,
}: {
  data?: ShareRow[];
  renderActions: (row: ShareRow) => ReactNode;
}) {
  const { t, labels } = useMessages();
  const { cloudMode } = useConfig();
  const { isMobile } = useMobile();

  const getUrl = (slug: string) => {
    if (cloudMode) {
      return `${process.env.cloudUrl}/share/${slug}`;
    }

    const origin = typeof window !== 'undefined' ? window.location.origin : '';

    return `${origin}${process.env.basePath || ''}/share/${slug}`;
  };

  return (
    <div style={{ width: '100%' }}>
      {!isMobile && (
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: desktopGridTemplateColumns,
            gap: '16px',
            alignItems: 'center',
            padding: '0 0 12px',
            borderBottom: rowBorder,
          }}
        >
          <Text weight="bold">{t(labels.name)}</Text>
          <Text weight="bold">{t(labels.shareUrl)}</Text>
          <div />
        </div>
      )}
      <div>
        {data.map(row => {
          const url = getUrl(row.slug);

          if (isMobile) {
            return (
              <div
                key={row.id}
                style={{
                  padding: '12px 0',
                  borderBottom: rowBorder,
                }}
              >
                <Text weight="bold">{row.name}</Text>
                <div style={{ marginTop: '8px' }}>
                  <ShareUrlCell url={url} value={row.slug} />
                </div>
                <Row justifyContent="flex-end" style={{ marginTop: '12px' }}>
                  {renderActions(row)}
                </Row>
              </div>
            );
          }

          return (
            <div
              key={row.id}
              style={{
                display: 'grid',
                gridTemplateColumns: desktopGridTemplateColumns,
                gap: '16px',
                alignItems: 'center',
                minHeight: '56px',
                padding: '12px 0',
                borderBottom: rowBorder,
              }}
            >
              <Text>{row.name}</Text>
              <ShareUrlCell url={url} value={url} />
              <Row justifyContent="flex-end">{renderActions(row)}</Row>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ShareUrlCell({ url, value }: { url: string; value: string }) {
  return (
    <Row alignItems="center" gap="1" minWidth="0" width="100%" overflow="hidden">
      <Row alignItems="center" gap minWidth="0" style={{ flex: 1 }}>
        <Text title={url} style={{ minWidth: 0, flex: 1, overflowWrap: 'anywhere' }}>
          <a
            href={url}
            target="_blank"
            rel="noreferrer"
            className="underline decoration-edge underline-offset-4 hover:text-foreground-primary hover:decoration-primary"
          >
            {value}
          </a>
        </Text>
        <Icon size="sm" strokeColor="muted" style={{ flexShrink: 0 }}>
          <ExternalLink />
        </Icon>
      </Row>
      <CopyButton value={url} label="Copy URL" />
    </Row>
  );
}

